import { z } from "zod";

export const TIME_ZONE = "America/Los_Angeles";

export const SCORE_VERSION = "dinner-date-scarcity-v1";

const nonempty = z.string().trim().min(1);

const timestamp = z.iso
  .datetime({ offset: true })
  .transform((value) => new Date(value).toISOString());

const date = z.iso.date();

const httpUrl = z.url({ protocol: /^https?$/ });

const resyUrl = z.url({ protocol: /^https$/, hostname: /^resy\.com$/ }).refine((value) => {
  const url = new URL(value);

  return url.pathname.includes("/venues/") && !url.search && !url.hash;
}, "Use a canonical Resy venue URL without query parameters");

export function localDate(instant: string): string {
  return new Intl.DateTimeFormat("en-CA", {
    timeZone: TIME_ZONE,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).format(new Date(instant));
}

// Calendar arithmetic uses UTC only to avoid adding 24 hours across local DST changes.
export function addDays(day: string, count: number): string {
  const value = new Date(`${day}T00:00:00Z`);
  value.setUTCDate(value.getUTCDate() + count);

  return value.toISOString().slice(0, 10);
}

export const evidenceSchema = z.strictObject({
  url: httpUrl,
  observedAt: timestamp,
  quote: nonempty,
});

const slotSchema = z.strictObject({
  time: z.string().regex(/^(?:(?:18|19|20):[0-5]\d|21:00)$/),
  type: nonempty,
  price: nonempty.nullable(),
});

const observationBase = z.strictObject({
  diningDate: date,
  observedAt: timestamp,
  evidence: z.array(evidenceSchema).min(1),
});

export const observationSchema = z.discriminatedUnion("status", [
  observationBase.extend({
    status: z.literal("available"),
    slots: z.array(slotSchema).min(1),
  }),
  observationBase.extend({
    status: z.literal("unavailable"),
    // An empty calendar alone cannot establish that released dinner inventory is gone.
    releaseEvidence: evidenceSchema,
    serviceEvidence: evidenceSchema,
  }),
  observationBase.extend({ status: z.literal("non_service") }),
  observationBase.extend({ status: z.literal("unreleased") }),
  observationBase.extend({ status: z.literal("unknown") }),
  observationBase.extend({ status: z.literal("collection_error") }),
]);

export const restaurantCaptureSchema = z
  .strictObject({
    name: nonempty,
    resyUrl,
    address: nonempty.nullable(),
    geography: z.enum(["san_francisco", "outside_san_francisco", "unknown"]),
    eligibility: z.enum(["eligible", "excluded", "unresolved"]),
    reason: nonempty,
    bookingPolicy: nonempty.nullable(),
    evidence: z.array(evidenceSchema).min(1),
    observations: z.array(observationSchema).max(28),
  })
  .superRefine((restaurant, context) => {
    if (restaurant.eligibility === "eligible" && restaurant.geography !== "san_francisco") {
      context.addIssue({
        code: "custom",
        message: "Eligible restaurants must be confirmed within SF",
      });
    }

    const dates = new Set<string>();

    for (const observation of restaurant.observations) {
      if (dates.has(observation.diningDate)) {
        context.addIssue({
          code: "custom",
          message: `Duplicate dining date: ${observation.diningDate}`,
        });
      }

      dates.add(observation.diningDate);
    }
  });

export const collectionSchema = z
  .strictObject({
    schemaVersion: z.literal(1),
    id: nonempty,
    startedAt: timestamp,
    finishedAt: timestamp,
    discoveryUrl: httpUrl,
    discoveryComplete: z.boolean(),
    selection: nonempty,
    collector: nonempty,
    procedure: z.array(nonempty).min(1),
    limitations: z.array(nonempty),
    restaurants: z.array(restaurantCaptureSchema).min(1),
  })
  .superRefine((collection, context) => {
    const anchor = localDate(collection.startedAt);
    const start = Date.parse(collection.startedAt);
    const finish = Date.parse(collection.finishedAt);

    if (finish < start || localDate(collection.finishedAt) !== anchor) {
      context.addIssue({
        code: "custom",
        message: "A collection must finish on its starting SF date",
      });
    }

    const urls = new Set<string>();

    for (const restaurant of collection.restaurants) {
      if (urls.has(restaurant.resyUrl)) {
        context.addIssue({
          code: "custom",
          message: `Duplicate restaurant: ${restaurant.resyUrl}`,
        });
      }

      urls.add(restaurant.resyUrl);

      for (const observation of restaurant.observations) {
        const observed = Date.parse(observation.observedAt);

        if (observed < start || observed > finish || localDate(observation.observedAt) !== anchor) {
          context.addIssue({
            code: "custom",
            message: "Observation is outside the collection interval",
          });
        }

        if (observation.diningDate <= anchor || observation.diningDate > addDays(anchor, 28)) {
          context.addIssue({ code: "custom", message: "Dining date is outside days 1–28" });
        }
      }
    }
  });

export type Collection = z.infer<typeof collectionSchema>;

export type RestaurantCapture = z.infer<typeof restaurantCaptureSchema>;

export type Observation = z.infer<typeof observationSchema>;

export type Evidence = z.infer<typeof evidenceSchema>;
import { addDays } from "./model.ts";
import type { RestaurantCapture } from "./model.ts";

export function scoreRestaurant(restaurant: RestaurantCapture, anchorDate: string) {
  const observations = new Map(restaurant.observations.map((item) => [item.diningDate, item]));

  return [1, 8, 15, 22].map((startDay) => {
    const counts = {
      available: 0,
      unavailable: 0,
      non_service: 0,
      unreleased: 0,
      unknown: 0,
      collection_error: 0,
      missing: 0,
    };

    for (let offset = startDay; offset < startDay + 7; offset++) {
      const observation = observations.get(addDays(anchorDate, offset));

      if (observation) {
        counts[observation.status]++;
      } else {
        counts.missing++;
      }
    }

    const assessed = counts.available + counts.unavailable;

    const incomplete =
      counts.unreleased + counts.unknown + counts.collection_error + counts.missing;

    let score: number | null = null;
    let reason: string | null = null;

    if (restaurant.eligibility !== "eligible") {
      reason = restaurant.reason;
    } else if (incomplete > 0) {
      reason =
        "Not every date has a released, assessed dinner service or confirmed non-service status";
    } else if (assessed === 0) {
      reason = "No regular dinner service dates in this band";
    } else {
      score = (100 * counts.unavailable) / assessed;
    }

    return { startDay, endDay: startDay + 6, counts, assessed, score, reason };
  });
}
# Resy SF data collection

## Goal and scope

Prioritize restaurants that are hard to access through public Resy reservations
for two. This is observed reservation scarcity, not occupancy, booking volume,
prestige, or a forecast of demand.

Include restaurants physically within San Francisco city limits. A Resy city
listing is a discovery source, not geographic proof. Count regular dinner
reservations starting from 18:00 through 21:00 inclusive in
`America/Los_Angeles`. Public recurring tasting menus, deposits, counter seats,
and outdoor tables count. Special events, waitlists, notifications, and
membership/card-restricted offers do not.

## Commands

Run commands from the repository root. The single data entry point explains
its commands and workflow:

```sh
vp run data --help
vp run data migrate
vp run data schema
vp run data validate data/collections/<capture>.json
vp run data import data/collections/<capture>.json
vp run data report
vp run data inspect <collection-id>
```

`DATABASE_URL` selects the local SQLite file, defaulting to `dev.db`. The existing
`.env.local` and `.env` configuration is respected. Override `DATABASE_URL` in
the shell to use a separate database. SQLite databases and sidecars stay local;
versioned JSON collection artifacts and Drizzle migrations reproduce the data.

`schema` derives JSON Schema from Zod. `validate` also enforces cross-field rules
that JSON Schema cannot express. It does not open a database. Imports validate
before writing and use one transaction per collection. Exact retries are
no-ops. Reusing an ID with different evidence fails; a corrected or refreshed
capture needs a new ID. Failed imports leave no partial collection behind.

The importer is rerunnable. Browser collection remains an evidence-gathering
workflow; there is no unattended scraper or scheduler yet. Preserve each
scout's verified collection procedure so later automation can reproduce it.

## Depth-first collection

1. Open the SF discovery page in an isolated `agent-browser` session. Record
   the actual UTC observation time and SF local date. Never share another
   scout's browser session.
2. Record canonical venue URLs and names from settled listing results. Track
   pagination and explain selection. A partial listing is not a full census.
3. Finish one restaurant before expanding. Confirm its address, regular dinner
   reservation eligibility, service schedule, and release policy. Use Resy and
   the restaurant's official linked pages, retaining URLs and relevant quotes.
4. Check tomorrow through day 7 first, then days 8–28. Confirm that the rendered
   party-size and date controls match each requested observation. A URL alone
   does not prove the application applied its parameters.
5. Wait for the reservation results to settle. A loading state or transient
   "No results" is not evidence of missing inventory. Capture every qualifying
   visible time, reservation type, and displayed price without initiating a
   reservation.
6. Save the observations and reproducible procedure in one collection artifact.
   Run `validate`, review its evidence, and import it before broadening coverage.
7. On interruption, save only observations actually obtained. Missing dates
   remain missing. Close only the session owned by that scout. A later visit is
   a new observation, not a silent continuation of an earlier timestamp.

Use bounded parallel scouts with disjoint restaurant assignments. The first
scouting budget is 60 minutes of elapsed time. Prefer completed restaurant
records over wide but shallow coverage. Stop on access challenges; do not turn
blocked requests into unavailable dates. Report unresolved collection failures.

## Observation states

| State | Required interpretation |
| --- | --- |
| `available` | At least one qualifying public dinner slot is visible. |
| `unavailable` | No qualifying slot; service and release are evidenced. |
| `non_service` | Evidence establishes no regular dinner service that date. |
| `unreleased` | Evidence establishes inventory has not been released. |
| `unknown` | Evidence cannot distinguish the relevant states. |
| `collection_error` | The attempted collection failed. |

Missing dates have no observation row. The scoring output counts them
separately. An unavailable observation requires additional `releaseEvidence`
and `serviceEvidence`; an empty calendar alone is insufficient. Evidence
objects contain the source URL, observation timestamp, and relevant quote.

Zod rejects duplicate restaurants or dining dates, dates outside the horizon,
observations outside the collection interval, invalid dinner times, and eligible
restaurants whose SF geography is unconfirmed. Each collection stays within one
SF calendar date; split a run at local midnight. Zod establishes structural
consistency, not the truth of a scout's interpretation. Review the source quotes
before accepting classification, especially for fully unavailable restaurants.

Exclude closed venues, listings using another platform for regular reservations,
event-only listings, lunch-only venues, and venues outside SF. Keep the reason.
Ambiguous eligibility stays unresolved. Neither excluded nor unresolved venues
receive scores, even if their observations contain no availability.

## Scoring and normalization

For each seven-day band:

```text
assessed = available dinner dates + unavailable dinner dates
score = 100 * unavailable dinner dates / assessed
```

The headline uses days 1–7. Supporting bands use days 8–14, 15–21, and 22–28.
Every assessed date has equal weight. A date with one 18:00 slot counts as
available, just like a date with many slots. Visible slot counts do not reveal
seating capacity and do not enter the score.

Publish a band's score only when all seven dates have known outcomes:
`available`, `unavailable`, or evidenced `non_service`. At least one date must
be assessed. Any missing, unknown, unreleased, or failed date makes that band's
score null. For example, two unavailable dates, three available dates, and two
non-service dates yield `100 * 2 / 5 = 40`.

The scale is fixed, not a percentile or a subset-dependent min/max transform.
Adding restaurants does not change existing scores. Higher means harder access;
100 means no qualifying availability on any assessed dinner date, not confirmed
full occupancy. Null does not mean zero.

A common headline week avoids rewarding a seven-day booking window for the
three weeks it has not released. Such a restaurant may have a valid headline
and null later bands. Restaurants releasing fewer than seven days ahead may
remain unranked. Service schedules still differ; always show assessed counts
and non-service dates rather than claiming equal statistical confidence.

Friday and Saturday are the weekend supporting signal. Earliest observed
availability and weekend available-date counts cover all 28 days; they are
lower-bound observations if later dates are missing or unreleased. They do not
break score ties. Display tied scores as ties, with name ordering only for
stable presentation.

## Storage and downstream use

Drizzle manages these tables:

- `collections`: interval, SF anchor date, selection, collector, reproducible
  procedure, limitations, input hash, and schema/scoring versions.
- `restaurant_snapshots`: identity, address, eligibility, policy, and source
  evidence as observed in that collection.
- `dinner_observations`: dated outcomes and the validated Zod record, including
  qualifying slots and source evidence. One row per restaurant/date/collection.
- `scarcity_scores`: four reproducible band scores with denominators, every
  coverage-state count, and the reason a score is absent.

The `restaurant_ranking` view selects the latest collection per canonical venue
URL. A newer incomplete capture remains incomplete; it never silently borrows
an older complete score. `report` sorts this view by score descending with nulls
last, then by name. This view can mix collection dates, so the eventual UI must
show observation intervals and freshness, or restrict comparisons to one anchor
date. `inspect` exposes one collection's full supporting data.

For a simple SQL consumer:

```sql
SELECT name, score, assessed, available, unavailable, non_service,
       unreleased, unknown, collection_error, missing,
       earliest_available_date, booking_policy, anchor_date, score_reason
FROM restaurant_ranking
ORDER BY score DESC, name;
```

## History and limits

Observation time is when we checked; dining date is when dinner would happen.
Repeated snapshots preserve both, allowing future analysis at equivalent lead
times. Querying a past dining date cannot reconstruct historic availability.
No historical scarcity or forecasting claim is supported by the first snapshot.

Scarcity can reflect demand, capacity, held-back inventory, cancellations, or
reservation policy. Public evidence cannot reliably separate all these causes.
A small convenience subset cannot establish the busiest restaurants citywide.
The capture's selection and limitations are part of the result, not footnotes
to discard when building the UI.

import { createHash } from "node:crypto";

import { desc, eq } from "drizzle-orm";
import type { BetterSQLite3Database } from "drizzle-orm/better-sqlite3";

import * as schema from "../db/schema.ts";
import { localDate, SCORE_VERSION } from "./model.ts";
import type { Collection } from "./model.ts";
import { scoreRestaurant } from "./score.ts";

type ScarcityDatabase = BetterSQLite3Database<typeof schema>;

/** Import one validated, immutable collection atomically. Exact retries are no-ops. */
export function importCollection(db: ScarcityDatabase, collection: Collection) {
  const inputHash = createHash("sha256").update(JSON.stringify(collection)).digest("hex");
  const anchorDate = localDate(collection.startedAt);

  return db.transaction((transaction) => {
    const existing = transaction
      .select()
      .from(schema.collections)
      .where(eq(schema.collections.id, collection.id))
      .get();

    if (existing) {
      if (existing.inputHash !== inputHash) {
        throw new Error(
          `Collection ${collection.id} already exists with different evidence; use a new ID`,
        );
      }

      return { imported: false, restaurants: collection.restaurants.length };
    }

    transaction
      .insert(schema.collections)
      .values({
        id: collection.id,
        inputHash,
        schemaVersion: collection.schemaVersion,
        scoreVersion: SCORE_VERSION,
        startedAt: collection.startedAt,
        finishedAt: collection.finishedAt,
        anchorDate,
        discoveryUrl: collection.discoveryUrl,
        discoveryComplete: collection.discoveryComplete,
        selection: collection.selection,
        collector: collection.collector,
        procedure: collection.procedure,
        limitations: collection.limitations,
      })
      .run();

    for (const restaurant of collection.restaurants) {
      const { observations, ...assessment } = restaurant;
      const identity = { collectionId: collection.id, resyUrl: restaurant.resyUrl };
      transaction
        .insert(schema.restaurantSnapshots)
        .values({
          ...assessment,
          collectionId: collection.id,
        })
        .run();

      for (const observation of observations) {
        transaction
          .insert(schema.dinnerObservations)
          .values({
            ...identity,
            diningDate: observation.diningDate,
            observedAt: observation.observedAt,
            status: observation.status,
            detail: observation,
          })
          .run();
      }

      for (const band of scoreRestaurant(restaurant, anchorDate)) {
        transaction
          .insert(schema.scarcityScores)
          .values({
            ...identity,
            startDay: band.startDay,
            endDay: band.endDay,
            available: band.counts.available,
            unavailable: band.counts.unavailable,
            nonService: band.counts.non_service,
            unreleased: band.counts.unreleased,
            unknown: band.counts.unknown,
            collectionError: band.counts.collection_error,
            missing: band.counts.missing,
            assessed: band.assessed,
            score: band.score,
            reason: band.reason,
          })
          .run();
      }
    }

    return { imported: true, restaurants: collection.restaurants.length };
  });
}

export function readRanking(db: ScarcityDatabase) {
  // SQLite sorts NULL last with DESC. Equal scores remain ties, ordered by name for display.
  return db
    .select()
    .from(schema.restaurantRanking)
    .orderBy(desc(schema.restaurantRanking.score), schema.restaurantRanking.name)
    .all();
}
import { readFile } from "node:fs/promises";
import { parseArgs } from "node:util";

import { eq } from "drizzle-orm";
import { migrate } from "drizzle-orm/better-sqlite3/migrator";
import { z } from "zod";

import * as tables from "../db/schema.ts";
import { collectionSchema } from "./model.ts";
import { importCollection, readRanking } from "./store.ts";

const help = `Resy SF reservation-scarcity data pipeline

Usage: vp run data <command> [argument]
       vp run data --help

Commands:
  migrate                Apply checked-in Drizzle migrations to the local SQLite DB.
  schema                 Print the collection JSON Schema derived from Zod.
  validate <file.json>   Validate evidence without opening or modifying the DB.
  import <file.json>     Validate, score, and atomically store one collection.
  report                 Print latest-per-restaurant ranking as JSON, scores first.
  inspect <collection>   Print one collection's provenance, observations, and scores.

Workflow:
  1. vp run data migrate
  2. Collect public Resy evidence using agent-browser; see docs/data-collection.md.
  3. vp run data validate data/collections/<capture>.json
  4. vp run data import data/collections/<capture>.json
  5. vp run data report

Configuration:
  DATABASE_URL selects a SQLite file (default dev.db).
  Existing .env.local and .env configuration is respected.

Evidence and scoring:
  Party of two; public regular dinner starting 18:00–21:00, San Francisco time.
  Observe days 1–28; headline score compares days 1–7 on a fixed 0–100 scale.
  Missing, unknown, unreleased, or failed dates prevent a band's publication.
  Closed/event-only/other-platform venues are not evidence of high demand.
  JSON Schema describes fields; validate also checks cross-field Zod invariants.

Retries and history:
  Exact re-imports are no-ops. Changed evidence requires a new collection ID.
  Failed imports roll back completely. New snapshots preserve prior observations.
  A snapshot is not a forecast. Keep timestamps and collection limitations visible.
`;

async function main() {
  const { values, positionals } = parseArgs({
    allowPositionals: true,
    options: { help: { type: "boolean", short: "h" } },
  });

  const [command, argument, ...extra] = positionals;

  if (values.help || !command) {
    console.log(help);

    return;
  }

  if (extra.length > 0) {
    throw new Error("Too many arguments");
  }

  switch (command) {
    case "schema": {
      if (argument) {
        throw new Error("Usage: vp run data schema");
      }

      console.log(JSON.stringify(z.toJSONSchema(collectionSchema, { io: "input" }), null, 2));
      break;
    }

    case "validate":
    case "import": {
      if (!argument) {
        throw new Error(`Usage: vp run data ${command} <collection.json>`);
      }

      const collection = collectionSchema.parse(JSON.parse(await readFile(argument, "utf8")));

      if (command === "validate") {
        console.log(
          `Valid collection ${collection.id}: ${collection.restaurants.length} restaurants`,
        );
        break;
      }

      const { db } = await import("../db/index.ts");

      try {
        console.log(JSON.stringify(importCollection(db, collection)));
      } finally {
        db.$client.close();
      }

      break;
    }

    case "migrate":
    case "report": {
      if (argument) {
        throw new Error(`Usage: vp run data ${command}`);
      }

      const { db } = await import("../db/index.ts");

      try {
        if (command === "migrate") {
          migrate(db, { migrationsFolder: "drizzle" });
          console.log("Database migrations applied");
        } else {
          console.log(JSON.stringify(readRanking(db), null, 2));
        }
      } finally {
        db.$client.close();
      }

      break;
    }

    case "inspect": {
      if (!argument) {
        throw new Error("Usage: vp run data inspect <collection-id>");
      }

      const { db } = await import("../db/index.ts");

      try {
        const collection = db
          .select()
          .from(tables.collections)
          .where(eq(tables.collections.id, argument))
          .get();

        if (!collection) {
          throw new Error(`Unknown collection: ${argument}`);
        }

        console.log(
          JSON.stringify(
            {
              collection,
              restaurants: db
                .select()
                .from(tables.restaurantSnapshots)
                .where(eq(tables.restaurantSnapshots.collectionId, argument))
                .all(),
              observations: db
                .select()
                .from(tables.dinnerObservations)
                .where(eq(tables.dinnerObservations.collectionId, argument))
                .all(),
              scores: db
                .select()
                .from(tables.scarcityScores)
                .where(eq(tables.scarcityScores.collectionId, argument))
                .all(),
            },
            null,
            2,
          ),
        );
      } finally {
        db.$client.close();
      }

      break;
    }

    default:
      throw new Error(`Unknown command: ${command}`);
  }
}

try {
  await main();
} catch (error) {
  console.error(error instanceof Error ? error.message : "Data command failed");
  console.error("Run vp run data --help for commands and collection guidance.");
  process.exitCode = 1;
}
import { createFileRoute } from "@tanstack/react-router";

