  --sea-ink: #173a40;
  --sea-ink-soft: #416166;
  --lagoon: #4fb8b2;
  --lagoon-deep: #328f97;
  --palm: #2f6a4a;
  --sand: #e7f0e8;
  --foam: #f3faf5;
  --surface: rgba(255, 255, 255, 0.74);
