function minutesAfterStart(minutes: number): string {
  return new Date(Date.parse(STARTED_AT) + minutes * 60_000).toISOString();
}

function observationFor(
  code: string,
  diningDate: string,
  evidence: Evidence,
  slots: Slot[],
): Observation | null {
  const base = { diningDate, observedAt: evidence.observedAt, evidence: [evidence] };

  switch (code) {
    case "A": {
      const day = Number(diningDate.slice(-2));
      const count = 1 + (day % Math.max(slots.length, 1));

      return { ...base, status: "available", slots: slots.slice(0, count) };
    }
    case "U":
      return {
        ...base,
        status: "unavailable",
        releaseEvidence: { ...evidence, quote: "Calendar shows this date as released" },
        serviceEvidence: { ...evidence, quote: "Dinner service listed for this weekday" },
      };
    case "N":
      return { ...base, status: "non_service" };
    case "R":
      return { ...base, status: "unreleased" };
    case "?":
      return { ...base, status: "unknown" };
    case "E":
      return { ...base, status: "collection_error" };
    case "-":
      return null;
    default:
      throw new Error(`Unknown day code: ${code}`);
  }
}

function capture(profile: Profile, index: number): RestaurantCapture {
  const resyUrl = `https://resy.com/cities/san-francisco-ca/venues/${profile.slug}`;
  const codes = profile.days.replaceAll(" ", "");
  const anchor = localDate(STARTED_AT);
  const observations: Observation[] = [];

  for (const [offset, code] of [...codes].entries()) {
    const evidence = {
      url: resyUrl,
      observedAt: minutesAfterStart(index * MINUTES_PER_VENUE + offset * 0.1),
      quote: `Synthetic observation for party of 2, code ${code}`,
    };
    const observation = observationFor(code, addDays(anchor, offset + 1), evidence, profile.slots);

    if (observation) {
      observations.push(observation);
    }
  }

  return {
    name: profile.name,
    resyUrl,
    address: profile.address,
    geography: profile.geography,
    eligibility: profile.eligibility,
    reason: profile.reason,
    bookingPolicy: profile.bookingPolicy,
    evidence: [
      { url: resyUrl, observedAt: minutesAfterStart(index * MINUTES_PER_VENUE), quote: profile.reason },
    ],
    observations,
  };
}

const collection = collectionSchema.parse({
  schemaVersion: 1,
  id: "prototype-synthetic-2026-09-30",
  startedAt: STARTED_AT,
  finishedAt: FINISHED_AT,
  discoveryUrl: "https://resy.com/cities/san-francisco-ca",
  discoveryComplete: false,
  selection: "Synthetic prototype data: 28 fictional venues covering every eligibility and observation state",
  collector: "src/prototype/seed.ts",
  procedure: [
