    "Fictional venues; not a Resy observation",
    "Partial listing; not a citywide census",
    "One snapshot; does not establish persistent scarcity",
  ],
  restaurants: profiles.map(capture),
});

migrate(db, { migrationsFolder: "drizzle" });
console.log(JSON.stringify(importCollection(db, collection)));
db.$client.close();

