// PROTOTYPE — client-safe view model shared by every layout.
import type { Observation } from "#/scarcity/model.ts";

import type { Dashboard } from "./dashboard.server.ts";

export type Restaurant = Dashboard["restaurants"][number];

export type Collection = Dashboard["collections"][number];

export type Day = Restaurant["days"][number];

export type Band = Restaurant["bands"][number];

export type DayStatus = Observation["status"] | "missing";

export type Slot = Extract<Observation, { status: "available" }>["slots"][number];

export type Standing = "ranked" | "incomplete" | "excluded" | "unresolved";

export const STANDINGS: { standing: Standing; title: string; note: string }[] = [
  { standing: "ranked", title: "Ranked", note: "Complete days 1–7 evidence" },
  {
    standing: "incomplete",
    title: "Unscored",
    note: "Regular Resy dinner service, but the headline week has gaps",
  },
  {
    standing: "unresolved",
    title: "Unresolved",
    note: "Evidence cannot tell booked apart from not taking reservations",
  },
  {
    standing: "excluded",
    title: "Excluded",
    note: "Not comparable: closed, another platform, events only, or outside SF",
  },
];

export const STATUS_LABEL: Record<DayStatus, string> = {
  unavailable: "No opening",
  available: "Opening",
  non_service: "No dinner service",
  unreleased: "Not yet released",
  unknown: "Unclear",
  collection_error: "Check failed",
  missing: "Not checked",
};

export const LEGEND: DayStatus[] = [
  "unavailable",
  "available",
  "non_service",
  "unreleased",
  "unknown",
];

export function standingOf(restaurant: Restaurant): Standing {
  if (restaurant.eligibility === "excluded") {
    return "excluded";
  }

  if (restaurant.eligibility === "unresolved") {
    return "unresolved";
  }

  return restaurant.score === null ? "incomplete" : "ranked";
}

/** Groups in display order; each group keeps the ranking's score-then-name order. */
export function groupByStanding(restaurants: Restaurant[]) {
  const groups = new Map<Standing, Restaurant[]>(STANDINGS.map(({ standing }) => [standing, []]));

  for (const restaurant of restaurants) {
    groups.get(standingOf(restaurant))?.push(restaurant);
  }

  return STANDINGS.map((meta) => ({ ...meta, restaurants: groups.get(meta.standing) ?? [] }));
}

/** Standard competition ranking over the ranked group: equal scores share a rank. */
export function competitionRanks(ranked: Restaurant[]) {
  const ranks = new Map<string, { rank: number; tied: boolean }>();
  const countByScore = new Map<number | null, number>();

  for (const restaurant of ranked) {
    countByScore.set(restaurant.score, (countByScore.get(restaurant.score) ?? 0) + 1);
  }

  let previousScore: number | null = null;
  let rank = 0;

  for (const [index, restaurant] of ranked.entries()) {
    if (index === 0 || restaurant.score !== previousScore) {
      rank = index + 1;
    }

    previousScore = restaurant.score;
    ranks.set(restaurant.slug, { rank, tied: (countByScore.get(restaurant.score) ?? 0) > 1 });
  }

  return ranks;
}

export function dayStatus(day: Day): DayStatus {
  return day.observation?.status ?? "missing";
}

export function slotsOf(day: Day): Slot[] {
  return day.observation?.status === "available" ? day.observation.slots : [];
}

export function openings(restaurant: Restaurant) {
  return restaurant.days.flatMap((day) =>
    slotsOf(day).map((slot) => ({ diningDate: day.diningDate, slot })),
  );
}

export function nextOpening(restaurant: Restaurant) {
  for (const day of restaurant.days) {
    const [first] = slotsOf(day).toSorted((a, b) => a.time.localeCompare(b.time));

    if (first) {
      return { diningDate: day.diningDate, slot: first };
    }
  }

  return null;
}

export function headline(restaurant: Restaurant): Band | undefined {
  return restaurant.bands.find((band) => band.startDay === 1);
}

export function tierOf(score: number) {
  if (score === 100) {
    return "No openings";
  }

  if (score >= 67) {
    return "Scarce";
  }

  if (score >= 34) {
    return "Limited";
  }

  return "Open";
}

export function formatScore(score: number) {
  return Math.round(score).toString();
}

// Dates are SF calendar dates; format them as UTC so server and client render identically.
function calendarDate(date: string) {
  return new Date(`${date}T12:00:00Z`);
}

const dayFormat = new Intl.DateTimeFormat("en-US", {
  timeZone: "UTC",
  weekday: "short",
  month: "short",
  day: "numeric",
});

const weekdayFormat = new Intl.DateTimeFormat("en-US", { timeZone: "UTC", weekday: "narrow" });

const monthDayFormat = new Intl.DateTimeFormat("en-US", {
  timeZone: "UTC",
  month: "short",
  day: "numeric",
});

const instantFormat = new Intl.DateTimeFormat("en-US", {
  timeZone: "America/Los_Angeles",
  hour: "numeric",
  minute: "2-digit",
});

export function formatDay(date: string) {
  return dayFormat.format(calendarDate(date));
}

export function formatMonthDay(date: string) {
  return monthDayFormat.format(calendarDate(date));
}

export function weekdayLetter(date: string) {
  return weekdayFormat.format(calendarDate(date));
}

export function dayOfMonth(date: string) {
  return calendarDate(date).getUTCDate();
}

/** Friday and Saturday are the weekend supporting signal. */
export function isWeekend(date: string) {
  const weekday = calendarDate(date).getUTCDay();

  return weekday === 5 || weekday === 6;
}

export function formatTime(time: string) {
  const [hours, minutes] = time.split(":").map(Number);
  const suffix = hours >= 12 ? "PM" : "AM";

  return `${hours % 12 || 12}:${minutes.toString().padStart(2, "0")} ${suffix}`;
}

export function formatInterval(collection: Collection) {
  const from = instantFormat.format(new Date(collection.startedAt));
  const through = instantFormat.format(new Date(collection.finishedAt));

  return `${formatDay(collection.anchorDate)} · ${from}–${through} PT`;
}

export function neighborhoodOf(address: string | null) {
  if (!address) {
    return "Address unconfirmed";
  }

  return address.split(",")[0];
}

