// PROTOTYPE — semantic building blocks shared by every layout. Layouts own arrangement.
import { ArrowUpRight, TriangleAlert } from "lucide-react";
import { cn } from "cn";

import { Tooltip, TooltipContent, TooltipTrigger } from "#/components/ui/tooltip";

import {
  LEGEND,
  STATUS_LABEL,
  dayOfMonth,
  dayStatus,
  formatDay,
  formatInterval,
  formatScore,
  formatTime,
  headline,
  isWeekend,
  nextOpening,
  openings,
  slotsOf,
  standingOf,
  streetOf,
  tierOf,
  weekdayLetter,
} from "./dashboard.ts";
import type { Band, Collection, Day, Restaurant } from "./dashboard.ts";

declare module "react" {
  interface CSSProperties {
    "--score"?: number;
  }
}

export function DayCell({ day, className }: { day: Day; className?: string }) {
  const status = dayStatus(day);
  const slots = slotsOf(day);

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span
          role="img"
          aria-label={`${formatDay(day.diningDate)}: ${STATUS_LABEL[status]}`}
          data-status={status}
          className={cn("day-cell", className)}
        />
      </TooltipTrigger>
      <TooltipContent side="top" className="px-2.5 py-2">
        <div className="font-medium">{formatDay(day.diningDate)}</div>
        <div className="opacity-70">
          {STATUS_LABEL[status]} · day {day.offset}
        </div>
        {slots.map((slot) => (
          <div key={`${slot.time}-${slot.type}`} className="mt-1 tabular">
            {formatTime(slot.time)} · {slot.type}
            {slot.price ? ` · ${slot.price}` : ""}
          </div>
        ))}
      </TooltipContent>
    </Tooltip>
  );
}

export function WeekStrip({ days, className }: { days: Day[]; className?: string }) {
  return (
    <div className={cn("grid grid-cols-7 gap-1", className)}>
      {days.slice(0, 7).map((day) => (
        <DayCell key={day.diningDate} day={day} />
      ))}
    </div>
  );
}

export function ScoreBar({ score, className }: { score: number; className?: string }) {
  return (
    <div className={cn("h-1 overflow-hidden rounded-full bg-border", className)}>
      <div className="heat-fill h-full rounded-full" style={{ width: `${score}%`, "--score": score }} />
    </div>
  );
}

export function Legend({ className }: { className?: string }) {
  return (
    <ul className={cn("flex flex-wrap items-center gap-x-4 gap-y-2 text-xs text-muted-foreground", className)}>
      {LEGEND.map((status) => (
        <li key={status} className="flex items-center gap-1.5">
          <span data-status={status} className="day-cell size-3" />
          {STATUS_LABEL[status]}
        </li>
      ))}
    </ul>
  );
}

/** Why a band has no score, from its coverage counts rather than a generic sentence. */
export function bandGap(band: Band) {
  const gaps = [
    [band.unreleased, "not released"],
    [band.unknown, "unclear"],
    [band.collectionError, "failed"],
    [band.missing, "not checked"],
  ] as const;

  const parts: string[] = [];

  for (const [count, label] of gaps) {
    if (count > 0) {
      parts.push(`${count} ${label}`);
    }
  }

  if (parts.length > 0) {
    return parts.join(" · ");
  }

  return band.assessed === 0 ? "No dinner service" : null;
}

export function bandLabel(band: Band) {
  return `Days ${band.startDay}–${band.endDay}`;
}

export function BandScores({ restaurant }: { restaurant: Restaurant }) {
  return (
    <dl className="grid grid-cols-4 overflow-hidden rounded-lg border bg-card">
      {restaurant.bands.map((band) => (
        <div key={band.startDay} className="border-l p-3 first:border-l-0">
          <dt className="text-[11px] font-medium text-muted-foreground">
            {band.startDay === 1 ? "Headline · " : ""}
            {bandLabel(band)}
          </dt>
          <dd
            className="mt-1 font-display text-2xl tabular heat-text"
            style={{ "--score": band.score ?? 0 }}
          >
            {band.score === null ? <span className="text-faint">—</span> : formatScore(band.score)}
          </dd>
          <dd className="mt-0.5 text-[11px] text-faint tabular">
            {band.score === null
              ? bandGap(band)
              : `${band.unavailable} of ${band.assessed} without opening`}
          </dd>
        </div>
      ))}
    </dl>
  );
}

export function Calendar({ restaurant, className }: { restaurant: Restaurant; className?: string }) {
  const weeks = [0, 7, 14, 21].map((start) => restaurant.days.slice(start, start + 7));

  return (
    <div className={cn("grid grid-cols-[3.5rem_repeat(7,minmax(0,1fr))] gap-1.5", className)}>
      <span />
      {weeks[0].map((day) => (
        <span
          key={day.diningDate}
          className={cn(
            "text-center text-[11px] font-medium text-faint",
            isWeekend(day.diningDate) && "text-foreground",
          )}
        >
          {weekdayLetter(day.diningDate)}
        </span>
      ))}
      {weeks.map((week, index) => (
        <div key={week[0].diningDate} className="contents">
          <span className="self-center text-[11px] text-faint tabular">
            {index * 7 + 1}–{index * 7 + 7}
          </span>
          {week.map((day) => (
            <div key={day.diningDate} className="relative">
              <DayCell day={day} className="w-full" />
              <span className="pointer-events-none absolute top-1 left-1.5 text-[9px] text-muted-foreground mix-blend-difference tabular">
                {dayOfMonth(day.diningDate)}
              </span>
            </div>
          ))}
        </div>
      ))}
    </div>
  );
}

export function OpeningsList({ restaurant, limit = 6 }: { restaurant: Restaurant; limit?: number }) {
  const all = openings(restaurant);

  if (all.length === 0) {
    return <p className="text-sm text-muted-foreground">No qualifying 6–9 PM table for two in 28 days.</p>;
  }

  return (
    <ul className="divide-y text-sm">
      {all.slice(0, limit).map(({ diningDate, slot }) => (
        <li key={`${diningDate}-${slot.time}-${slot.type}`} className="flex items-baseline gap-3 py-2">
          <span className="w-24 shrink-0 tabular">{formatDay(diningDate)}</span>
          <span className="w-16 shrink-0 font-mono text-xs tabular">{formatTime(slot.time)}</span>
          <span className="min-w-0 flex-1 truncate text-muted-foreground">{slot.type}</span>
          {slot.price ? <span className="text-xs text-faint">{slot.price}</span> : null}
        </li>
      ))}
      {all.length > limit ? (
        <li className="py-2 text-xs text-faint">+{all.length - limit} more openings</li>
      ) : null}
    </ul>
  );
}

export function EvidenceList({ restaurant }: { restaurant: Restaurant }) {
  return (
    <ul className="space-y-2">
      {restaurant.evidence.map((item) => (
        <li key={`${item.url}-${item.observedAt}`} className="text-sm">
          <blockquote className="border-l-2 pl-3 text-muted-foreground italic">“{item.quote}”</blockquote>
          <a
            href={item.url}
            target="_blank"
            rel="noreferrer"
            className="mt-1 inline-flex items-center gap-1 pl-3 text-xs text-faint hover:text-foreground"
          >
            {new URL(item.url).hostname}
            <ArrowUpRight className="size-3" />
          </a>
        </li>
      ))}
    </ul>
  );
}

export function NextOpening({ restaurant, className }: { restaurant: Restaurant; className?: string }) {
  const next = nextOpening(restaurant);

  if (!next) {
    return <span className={cn("text-faint", className)}>None in 28 days</span>;
  }

  return (
    <span className={cn("tabular", className)}>
      {formatDay(next.diningDate)} · {formatTime(next.slot.time)}
    </span>
  );
}

export function Section({
  title,
  children,
  className,
}: {
  title: string;
  children: React.ReactNode;
  className?: string;
}) {
  return (
    <section className={cn("space-y-3", className)}>
      <h3 className="text-xs font-medium tracking-wide text-muted-foreground uppercase">{title}</h3>
      {children}
    </section>
  );
}

/** Full supporting record for one restaurant; layouts decide where it lives. */
export function RestaurantDetail({ restaurant }: { restaurant: Restaurant }) {
  const standing = standingOf(restaurant);
  const band = headline(restaurant);

  return (
    <div className="space-y-8">
      <header className="flex items-start justify-between gap-6">
        <div className="min-w-0">
          <h2 className="font-display text-3xl leading-tight">{restaurant.name}</h2>
          <p className="mt-1 text-sm text-muted-foreground">{streetOf(restaurant.address)}</p>
        </div>
        {restaurant.score === null ? null : (
          <div className="text-right" style={{ "--score": restaurant.score }}>
            <div className="font-display text-6xl leading-none tabular heat-text">
              {formatScore(restaurant.score)}
            </div>
            <div className="mt-1 text-xs text-muted-foreground">{tierOf(restaurant.score)}</div>
          </div>
        )}
      </header>

      {standing === "ranked" ? (
        <p className="text-sm text-muted-foreground">
          <span className="text-foreground tabular">
            {restaurant.unavailable} of {restaurant.assessed}
          </span>{" "}
          dinner dates in the next week had no table for two between 6 and 9 PM
          {restaurant.nonService > 0 ? `; ${restaurant.nonService} closed for dinner` : ""}. Next
          opening: <NextOpening restaurant={restaurant} className="text-foreground" />.
        </p>
      ) : (
        <div className="flex gap-3 rounded-lg border border-warn/30 bg-warn/5 p-4 text-sm">
          <TriangleAlert className="mt-0.5 size-4 shrink-0 text-warn" />
          <div>
            <div className="font-medium">
              {standing === "incomplete" ? "Not scored: the headline week has gaps" : "Not scored"}
            </div>
            <p className="mt-1 text-muted-foreground">
              {standing === "incomplete" && band ? bandGap(band) : restaurant.eligibilityReason}
            </p>
          </div>
        </div>
      )}

      {restaurant.bands.length > 0 && standing !== "excluded" ? (
        <Section title="Seven-day bands">
          <BandScores restaurant={restaurant} />
        </Section>
      ) : null}

      {standing === "excluded" ? null : (
        <Section title="28-day dinner calendar">
          <Calendar restaurant={restaurant} />
          <Legend />
        </Section>
      )}

      {standing === "ranked" || standing === "incomplete" ? (
        <Section title="Openings, party of 2">
          <OpeningsList restaurant={restaurant} />
        </Section>
      ) : null}

      {restaurant.bookingPolicy ? (
        <Section title="Booking policy">
          <p className="text-sm leading-relaxed text-muted-foreground">{restaurant.bookingPolicy}</p>
        </Section>
      ) : null}

      <Section title="Evidence">
        <EvidenceList restaurant={restaurant} />
      </Section>
    </div>
  );
}

export function CollectionFacts({
  collections,
  total,
  className,
}: {
  collections: Collection[];
  total: number;
  className?: string;
}) {
  return (
    <div className={cn("flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-muted-foreground", className)}>
      {collections.map((collection) => (
        <span key={collection.id} className="tabular">
          Observed {formatInterval(collection)}
        </span>
      ))}
      <span className="text-faint">·</span>
      <span className="tabular">{total} venues</span>
      {collections.some((collection) => !collection.discoveryComplete) ? (
        <>
          <span className="text-faint">·</span>
          <span className="inline-flex items-center gap-1 text-warn">
            <TriangleAlert className="size-3" />
            Partial listing, not a citywide census
          </span>
        </>
      ) : null}
    </div>
  );
}

/** Methodology, normalization, and the collection's own limitations. */
export function MethodNotes({ collections, className }: { collections: Collection[]; className?: string }) {
  return (
    <div className={cn("grid gap-8 text-sm leading-relaxed md:grid-cols-3", className)}>
      <Section title="Score">
        <p className="rounded-md border bg-card px-3 py-2 font-mono text-xs">
          100 × dates without opening ÷ assessed dates
        </p>
        <p className="text-muted-foreground">
          For a party of two, 6–9 PM San Francisco time, on days 1–7 after the snapshot. Assessed dates
          are dinner dates with either an opening or evidenced released inventory and no opening.
          Each date counts once, however many slots it has.
        </p>
      </Section>
      <Section title="Normalization">
        <p className="text-muted-foreground">
          A fixed 0–100 scale, not a percentile, so adding restaurants never changes a score. 100 means
          no qualifying opening on any assessed date, not confirmed full occupancy. A week with any
          unreleased, unclear, failed, or unchecked date is not scored.
        </p>
        <Legend />
      </Section>
      <Section title="Not comparable">
        <p className="text-muted-foreground">
          Closed venues, other booking platforms, events-only listings, lunch-only venues, and venues
          outside SF are excluded with a reason. Where evidence cannot separate “booked” from “not
          taking reservations”, the venue stays unresolved. Neither gets a score.
        </p>
        {collections.map((collection) => (
          <ul key={collection.id} className="space-y-1 text-xs text-faint">
            <li>{collection.selection}</li>
            {collection.limitations.map((limitation) => (
              <li key={limitation}>· {limitation}</li>
            ))}
          </ul>
        ))}
      </Section>
    </div>
  );
}

// PROTOTYPE — floating variant switcher. ←/→ cycles layout, Shift+←/→ cycles style.
import { useEffect } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";

export const LAYOUTS = [
  { key: "table", name: "Ledger table" },
  { key: "leaderboard", name: "Leaderboard + panel" },
  { key: "heatmap", name: "Heatmap matrix" },
] as const;

export const STYLES = [
  { key: "obsidian", name: "Obsidian" },
  { key: "paper", name: "Paper" },
  { key: "velvet", name: "Velvet" },
] as const;

export type LayoutKey = (typeof LAYOUTS)[number]["key"];

export type StyleKey = (typeof STYLES)[number]["key"];

export const LAYOUT_KEYS = LAYOUTS.map((layout) => layout.key);

export const STYLE_KEYS = STYLES.map((style) => style.key);

function cycle<T extends { key: string }>(options: readonly T[], current: string, step: number): T {
  const index = options.findIndex((option) => option.key === current);

  return options[(index + step + options.length) % options.length];
}

function isTyping(target: EventTarget | null) {
  return (
    target instanceof HTMLElement &&
    (target.isContentEditable || ["INPUT", "TEXTAREA", "SELECT"].includes(target.tagName))
  );
}

export function PrototypeSwitcher({
  layout,
  style,
  onLayout,
  onStyle,
}: {
  layout: LayoutKey;
  style: StyleKey;
  onLayout: (key: LayoutKey) => void;
  onStyle: (key: StyleKey) => void;
}) {
  useEffect(() => {
    function onKeyDown(event: KeyboardEvent) {
      if (isTyping(event.target) || (event.key !== "ArrowLeft" && event.key !== "ArrowRight")) {
        return;
      }

      const step = event.key === "ArrowLeft" ? -1 : 1;

      if (event.shiftKey) {
        onStyle(cycle(STYLES, style, step).key);
      } else {
        onLayout(cycle(LAYOUTS, layout, step).key);
      }
    }

    window.addEventListener("keydown", onKeyDown);

    return () => window.removeEventListener("keydown", onKeyDown);
  }, [layout, style, onLayout, onStyle]);

  if (!import.meta.env.DEV) {
    return null;
  }

  const layoutIndex = LAYOUTS.findIndex((option) => option.key === layout);
  const styleIndex = STYLES.findIndex((option) => option.key === style);

  return (
    <div
      className="fixed bottom-5 left-1/2 z-[60] flex -translate-x-1/2 items-center gap-1 rounded-full bg-[#111] p-1 font-[system-ui] text-[13px] text-white shadow-[0_8px_30px_rgb(0_0_0/0.35),0_0_0_1px_rgb(255_255_255/0.12)]"
      aria-label="Prototype switcher"
    >
      <Stepper
        label="Layout"
        value={`${"ABC"[layoutIndex]} · ${LAYOUTS[layoutIndex].name}`}
        onPrevious={() => onLayout(cycle(LAYOUTS, layout, -1).key)}
        onNext={() => onLayout(cycle(LAYOUTS, layout, 1).key)}
      />
      <span className="h-5 w-px bg-white/15" />
      <Stepper
        label="Style"
        value={`${styleIndex + 1} · ${STYLES[styleIndex].name}`}
        onPrevious={() => onStyle(cycle(STYLES, style, -1).key)}
        onNext={() => onStyle(cycle(STYLES, style, 1).key)}
      />
    </div>
  );
}

function Stepper({
  label,
  value,
  onPrevious,
  onNext,
}: {
  label: string;
  value: string;
  onPrevious: () => void;
  onNext: () => void;
}) {
  return (
    <div className="flex items-center">
      <button
        type="button"
        onClick={onPrevious}
        aria-label={`Previous ${label.toLowerCase()}`}
        className="grid size-8 place-items-center rounded-full hover:bg-white/10"
      >
        <ChevronLeft className="size-4" />
      </button>
      <span className="min-w-44 text-center">
        <span className="text-white/50">{label}</span> {value}
      </span>
      <button
        type="button"
        onClick={onNext}
        aria-label={`Next ${label.toLowerCase()}`}
        className="grid size-8 place-items-center rounded-full hover:bg-white/10"
      >
        <ChevronRight className="size-4" />
      </button>
    </div>
  );
}

