// PROTOTYPE — Layout A: a dense, sortable ledger. Rows expand in place to their evidence.
import { Fragment, useState } from "react";
import { ArrowDown, ArrowUp, ChevronDown } from "lucide-react";
import { cn } from "cn";

import { competitionRanks, formatScore, groupByStanding, headline, nextOpening, streetOf, tierOf } from "./dashboard.ts";
import type { Restaurant } from "./dashboard.ts";
import type { Dashboard } from "./dashboard.server.ts";
import { CollectionFacts, MethodNotes, NextOpening, RestaurantDetail, ScoreBar, WeekStrip, bandGap } from "./parts.tsx";

type SortKey = "score" | "name" | "opening" | "weekend";

const COLUMN_COUNT = 8;

function sortRanked(ranked: Restaurant[], key: SortKey, descending: boolean) {
  const direction = descending ? -1 : 1;

  const value = (restaurant: Restaurant) => {
    switch (key) {
      case "score":
        return restaurant.score ?? -1;
      case "name":
        return restaurant.name;
      case "opening":
        return nextOpening(restaurant)?.diningDate ?? "9999";
      case "weekend":
        return restaurant.weekendAvailableDates;
    }
  };

  return ranked.toSorted((a, b) => {
    const left = value(a);
    const right = value(b);

    if (left === right) {
      return a.name.localeCompare(b.name);
    }

    return left < right ? -direction : direction;
  });
}

export function LedgerLayout({
  dashboard,
  venue,
  onSelectVenue,
}: {
  dashboard: Dashboard;
  venue: string | undefined;
  onSelectVenue: (slug: string | undefined) => void;
}) {
  const [sort, setSort] = useState<{ key: SortKey; descending: boolean }>({ key: "score", descending: true });
  const [ranked, ...others] = groupByStanding(dashboard.restaurants);
  const ranks = competitionRanks(ranked.restaurants);
  const rows = sortRanked(ranked.restaurants, sort.key, sort.descending);

  function toggle(slug: string) {
    onSelectVenue(venue === slug ? undefined : slug);
  }

  function sortBy(key: SortKey) {
    setSort((current) =>
      current.key === key ? { key, descending: !current.descending } : { key, descending: key !== "name" && key !== "opening" },
    );
  }

  return (
    <main className="mx-auto max-w-[1240px] px-6 pt-16 pb-36">
      <header className="flex flex-wrap items-end justify-between gap-x-10 gap-y-6">
        <div>
          <p className="text-xs font-medium text-muted-foreground">Resy · San Francisco · Party of 2 · 6–9 PM</p>
          <h1 className="mt-3 font-display text-5xl leading-none">Dinner scarcity</h1>
          <CollectionFacts className="mt-4" collections={dashboard.collections} total={dashboard.restaurants.length} />
        </div>
        <dl className="flex gap-8 text-sm">
          {[ranked, ...others].map((group) => (
            <div key={group.standing}>
              <dt className="text-xs text-muted-foreground">{group.title}</dt>
              <dd className="mt-1 font-display text-3xl leading-none tabular">{group.restaurants.length}</dd>
            </div>
          ))}
        </dl>
      </header>

      <details className="group mt-10 rounded-xl border bg-card/60 open:bg-card">
        <summary className="flex cursor-pointer list-none items-center justify-between px-5 py-3.5 text-sm font-medium">
          How the score works
          <ChevronDown className="size-4 text-muted-foreground transition-transform group-open:rotate-180" />
        </summary>
        <MethodNotes className="border-t px-5 py-6" collections={dashboard.collections} />
      </details>

      <div className="mt-6 overflow-x-auto rounded-xl border bg-card">
        <table className="w-full min-w-[980px] border-collapse text-sm">
          <thead>
            <tr className="border-b text-left text-xs text-muted-foreground">
              <th className="w-14 py-3 pl-5 font-medium">#</th>
              <SortHeader label="Restaurant" sortKey="name" sort={sort} onSort={sortBy} />
              <SortHeader label="Score" sortKey="score" sort={sort} onSort={sortBy} className="w-44" />
              <th className="w-48 py-3 font-medium">Next 7 dinners</th>
              <th className="w-24 py-3 text-right font-medium">No opening</th>
              <th className="w-32 py-3 pl-6 font-medium">Weeks 2 · 3 · 4</th>
              <SortHeader label="Next opening" sortKey="opening" sort={sort} onSort={sortBy} className="w-44" />
              <SortHeader label="Fri/Sat open" sortKey="weekend" sort={sort} onSort={sortBy} className="w-28 pr-5 text-right" />
            </tr>
          </thead>
          <tbody>
            {rows.map((restaurant) => (
              <Fragment key={restaurant.slug}>
                <RankedRow
                  restaurant={restaurant}
                  rank={ranks.get(restaurant.slug)}
                  expanded={venue === restaurant.slug}
                  onToggle={() => toggle(restaurant.slug)}
                />
                {venue === restaurant.slug ? <DetailRow restaurant={restaurant} /> : null}
              </Fragment>
            ))}
          </tbody>
          {others.map((group) =>
            group.restaurants.length === 0 ? null : (
              <tbody key={group.standing}>
                <tr>
                  <td colSpan={COLUMN_COUNT} className="border-t bg-muted/40 px-5 pt-6 pb-2">
                    <span className="text-xs font-medium text-foreground">{group.title}</span>
                    <span className="ml-2 text-xs text-muted-foreground">{group.note}</span>
                  </td>
                </tr>
                {group.restaurants.map((restaurant) => (
                  <Fragment key={restaurant.slug}>
                    <UnrankedRow
                      restaurant={restaurant}
                      expanded={venue === restaurant.slug}
                      onToggle={() => toggle(restaurant.slug)}
                    />
                    {venue === restaurant.slug ? <DetailRow restaurant={restaurant} /> : null}
                  </Fragment>
                ))}
              </tbody>
            ),
          )}
        </table>
      </div>
    </main>
  );
}

function SortHeader({
  label,
  sortKey,
  sort,
  onSort,
  className,
}: {
  label: string;
  sortKey: SortKey;
  sort: { key: SortKey; descending: boolean };
  onSort: (key: SortKey) => void;
  className?: string;
}) {
  const active = sort.key === sortKey;
  const Arrow = sort.descending ? ArrowDown : ArrowUp;

  return (
    <th
      className={cn("py-3 font-medium", className)}
      aria-sort={active ? (sort.descending ? "descending" : "ascending") : "none"}
    >
      <button
        type="button"
        onClick={() => onSort(sortKey)}
        className={cn("inline-flex items-center gap-1 hover:text-foreground", active && "text-foreground")}
      >
        {label}
        {active ? <Arrow className="size-3" /> : null}
      </button>
    </th>
  );
}

function RankedRow({
  restaurant,
  rank,
  expanded,
  onToggle,
}: {
  restaurant: Restaurant;
  rank: { rank: number; tied: boolean } | undefined;
  expanded: boolean;
  onToggle: () => void;
}) {
  const score = restaurant.score ?? 0;
  const supporting = restaurant.bands.filter((band) => band.startDay > 1);

  return (
    <tr
      onClick={onToggle}
      className={cn(
        "cursor-pointer border-b transition-colors hover:bg-accent/60",
        expanded && "bg-accent/60",
      )}
      style={{ "--score": score }}
    >
      <td className="py-3.5 pl-5 font-mono text-xs text-muted-foreground tabular">
        {rank?.tied ? "T" : ""}
        {rank?.rank}
      </td>
      <td className="py-3.5 pr-4">
        <button
          type="button"
          aria-expanded={expanded}
          className="text-left font-medium text-foreground outline-none focus-visible:underline"
        >
          {restaurant.name}
        </button>
        <div className="text-xs text-muted-foreground">{streetOf(restaurant.address)}</div>
      </td>
      <td className="py-3.5 pr-6">
        <div className="flex items-baseline gap-2">
          <span className="font-display text-2xl leading-none tabular heat-text">{formatScore(score)}</span>
          <span className="text-[11px] text-muted-foreground">{tierOf(score)}</span>
        </div>
        <ScoreBar score={score} className="mt-2 w-28" />
      </td>
      <td className="py-3.5 pr-6">
        <WeekStrip days={restaurant.days} className="w-40" />
      </td>
      <td className="py-3.5 text-right tabular">
        {restaurant.unavailable}
        <span className="text-muted-foreground"> / {restaurant.assessed}</span>
        {restaurant.nonService > 0 ? (
          <div className="text-[11px] text-faint">{restaurant.nonService} closed</div>
        ) : null}
      </td>
      <td className="py-3.5 pl-6 font-mono text-xs tabular">
        {supporting.map((band, index) => (
          <Fragment key={band.startDay}>
            {index > 0 ? <span className="text-faint"> · </span> : null}
            {band.score === null ? (
              <span className="text-faint" title={bandGap(band) ?? undefined}>—</span>
            ) : (
              <span className="heat-text" style={{ "--score": band.score }}>
                {formatScore(band.score)}
              </span>
            )}
          </Fragment>
        ))}
      </td>
      <td className="py-3.5 text-xs">
        <NextOpening restaurant={restaurant} />
      </td>
      <td className="py-3.5 pr-5 text-right tabular">{restaurant.weekendAvailableDates}</td>
    </tr>
  );
}

function UnrankedRow({
  restaurant,
  expanded,
  onToggle,
}: {
  restaurant: Restaurant;
  expanded: boolean;
  onToggle: () => void;
}) {
  const band = headline(restaurant);
  const hasObservations = restaurant.days.some((day) => day.observation !== null);
  const reason = restaurant.eligibility === "eligible" && band ? bandGap(band) : restaurant.eligibilityReason;

  return (
    <tr
      onClick={onToggle}
      className={cn("cursor-pointer border-b text-muted-foreground transition-colors hover:bg-accent/60", expanded && "bg-accent/60")}
    >
      <td className="py-3 pl-5 font-mono text-xs text-faint">—</td>
      <td className="py-3 pr-4">
        <button type="button" aria-expanded={expanded} className="text-left font-medium text-foreground/80 outline-none focus-visible:underline">
          {restaurant.name}
        </button>
        <div className="text-xs">{streetOf(restaurant.address)}</div>
      </td>
      <td className="py-3 pr-6 text-xs text-faint">No score</td>
      <td className="py-3 pr-6">
        {hasObservations ? <WeekStrip days={restaurant.days} className="w-40 opacity-80" /> : null}
      </td>
      <td colSpan={COLUMN_COUNT - 4} className="py-3 pr-5 pl-6 text-xs">
        {reason}
      </td>
    </tr>
  );
}

function DetailRow({ restaurant }: { restaurant: Restaurant }) {
  return (
    <tr className="border-b bg-background/40">
      <td colSpan={COLUMN_COUNT} className="px-5 py-8 md:px-14">
        <RestaurantDetail restaurant={restaurant} />
      </td>
    </tr>
  );
}

