// PROTOTYPE — Layout B: a ranked leaderboard beside a detail panel for the selected venue.
import { ChevronRight, DoorOpen } from "lucide-react";
import { cn } from "cn";

import { Tabs, TabsContent, TabsList, TabsTrigger } from "#/components/ui/tabs";

import {
  competitionRanks,
  formatDay,
  formatScore,
  formatTime,
  groupByStanding,
  headline,
  nextOpening,
  standingOf,
  streetOf,
  tierOf,
} from "./dashboard.ts";
import type { Restaurant } from "./dashboard.ts";
import type { Dashboard } from "./dashboard.server.ts";
import { CollectionFacts, MethodNotes, RestaurantDetail, ScoreBar, bandGap } from "./parts.tsx";

const PODIUM_SIZE = 3;

export function LeaderboardLayout({
  dashboard,
  venue,
  onSelectVenue,
}: {
  dashboard: Dashboard;
  venue: string | undefined;
  onSelectVenue: (slug: string | undefined) => void;
}) {
  const [ranked, ...others] = groupByStanding(dashboard.restaurants);
  const ranks = competitionRanks(ranked.restaurants);
  const selected =
    dashboard.restaurants.find((restaurant) => restaurant.slug === venue) ?? ranked.restaurants[0];

  const podium = ranked.restaurants.slice(0, PODIUM_SIZE);
  const rest = ranked.restaurants.slice(PODIUM_SIZE);

  return (
    <div className="grid min-h-screen lg:grid-cols-[minmax(380px,440px)_minmax(0,1fr)]">
      <aside className="border-r bg-card/40 lg:sticky lg:top-0 lg:h-screen lg:overflow-y-auto">
        <div className="px-7 pt-12 pb-8">
          <p className="text-xs font-medium text-muted-foreground">Resy · San Francisco · Party of 2</p>
          <h1 className="mt-3 font-display text-4xl leading-none">Hardest tables</h1>
          <CollectionFacts className="mt-4" collections={dashboard.collections} total={dashboard.restaurants.length} />
        </div>

        <ol className="space-y-1 px-3">
          {podium.map((restaurant) => (
            <li key={restaurant.slug}>
              <PodiumEntry
                restaurant={restaurant}
                rank={ranks.get(restaurant.slug)}
                selected={selected?.slug === restaurant.slug}
                onSelect={() => onSelectVenue(restaurant.slug)}
              />
            </li>
          ))}
        </ol>

        <ol className="mt-4 border-t px-3 pt-3">
          {rest.map((restaurant) => (
            <li key={restaurant.slug}>
              <ListEntry
                restaurant={restaurant}
                rank={ranks.get(restaurant.slug)}
                selected={selected?.slug === restaurant.slug}
                onSelect={() => onSelectVenue(restaurant.slug)}
              />
            </li>
          ))}
        </ol>

        <div className="mt-6 space-y-1 border-t px-3 pt-3 pb-28">
          {others.map((group) =>
            group.restaurants.length === 0 ? null : (
              <details key={group.standing} className="group" open={group.restaurants.some((item) => item.slug === selected?.slug)}>
                <summary className="flex cursor-pointer list-none items-center gap-2 rounded-md px-4 py-2.5 text-sm hover:bg-accent/60">
                  <ChevronRight className="size-3.5 text-muted-foreground transition-transform group-open:rotate-90" />
                  <span className="font-medium">{group.title}</span>
                  <span className="text-muted-foreground tabular">{group.restaurants.length}</span>
                  <span className="ml-auto truncate pl-3 text-xs text-faint">{group.note}</span>
                </summary>
                <ul className="pb-2">
                  {group.restaurants.map((restaurant) => (
                    <li key={restaurant.slug}>
                      <button
                        type="button"
                        onClick={() => onSelectVenue(restaurant.slug)}
                        className={cn(
                          "w-full rounded-md py-2 pr-4 pl-10 text-left hover:bg-accent/60",
                          selected?.slug === restaurant.slug && "bg-accent",
                        )}
                      >
                        <div className="text-sm">{restaurant.name}</div>
                        <div className="line-clamp-2 text-xs text-muted-foreground">
                          {unrankedReason(restaurant)}
                        </div>
                      </button>
                    </li>
                  ))}
                </ul>
              </details>
            ),
          )}
        </div>
      </aside>

      <main className="min-w-0 px-6 pt-10 pb-36 md:px-12 xl:px-16">
        <Tabs defaultValue="restaurant">
          <TabsList>
            <TabsTrigger value="restaurant">Restaurant</TabsTrigger>
            <TabsTrigger value="method">How the score works</TabsTrigger>
          </TabsList>
          <TabsContent value="restaurant" className="mt-10 max-w-4xl">
            {selected ? <Hero restaurant={selected} rank={ranks.get(selected.slug)} /> : null}
          </TabsContent>
          <TabsContent value="method" className="mt-10 max-w-4xl">
            <MethodNotes className="md:grid-cols-1" collections={dashboard.collections} />
          </TabsContent>
        </Tabs>
      </main>
    </div>
  );
}

function unrankedReason(restaurant: Restaurant) {
  const band = headline(restaurant);

  if (standingOf(restaurant) === "incomplete" && band) {
    return bandGap(band);
  }

  return restaurant.eligibilityReason;
}

function rankLabel(rank: { rank: number; tied: boolean } | undefined) {
  if (!rank) {
    return "";
  }

  return rank.tied ? `T${rank.rank}` : `${rank.rank}`;
}

function PodiumEntry({
  restaurant,
  rank,
  selected,
  onSelect,
}: {
  restaurant: Restaurant;
  rank: { rank: number; tied: boolean } | undefined;
  selected: boolean;
  onSelect: () => void;
}) {
  const score = restaurant.score ?? 0;

  return (
    <button
      type="button"
      onClick={onSelect}
      aria-current={selected}
      className={cn(
        "group grid w-full grid-cols-[2.75rem_minmax(0,1fr)_auto] items-center gap-3 rounded-xl px-4 py-4 text-left transition-colors hover:bg-accent/60",
        selected && "bg-accent shadow-[inset_0_0_0_1px_var(--border)]",
      )}
      style={{ "--score": score }}
    >
      <span className="font-display text-3xl leading-none text-faint tabular">{rankLabel(rank)}</span>
      <span className="min-w-0">
        <span className="block truncate font-display text-xl leading-tight">{restaurant.name}</span>
        <span className="mt-0.5 block truncate text-xs text-muted-foreground">
          {restaurant.unavailable} of {restaurant.assessed} dinners without a table
        </span>
      </span>
      <span className="text-right">
        <span className="block font-display text-4xl leading-none tabular heat-text">{formatScore(score)}</span>
      </span>
    </button>
  );
}

function ListEntry({
  restaurant,
  rank,
  selected,
  onSelect,
}: {
  restaurant: Restaurant;
  rank: { rank: number; tied: boolean } | undefined;
  selected: boolean;
  onSelect: () => void;
}) {
  const score = restaurant.score ?? 0;

  return (
    <button
      type="button"
      onClick={onSelect}
      aria-current={selected}
      className={cn(
        "grid w-full grid-cols-[2.75rem_minmax(0,1fr)_5rem_2.5rem] items-center gap-3 rounded-md px-4 py-2.5 text-left text-sm transition-colors hover:bg-accent/60",
        selected && "bg-accent",
      )}
      style={{ "--score": score }}
    >
      <span className="font-mono text-xs text-faint tabular">{rankLabel(rank)}</span>
      <span className="truncate">{restaurant.name}</span>
      <ScoreBar score={score} />
      <span className="text-right font-medium tabular heat-text">{formatScore(score)}</span>
    </button>
  );
}

function Hero({ restaurant, rank }: { restaurant: Restaurant; rank: { rank: number; tied: boolean } | undefined }) {
  const standing = standingOf(restaurant);
  const next = nextOpening(restaurant);

  return (
    <article className="space-y-10">
      <header className="flex flex-wrap items-end justify-between gap-8">
        <div className="min-w-0">
          <p className="text-xs font-medium text-muted-foreground">
            {standing === "ranked" ? `No. ${rankLabel(rank)} of the ranked week` : "Not ranked"}
          </p>
          <h2 className="mt-3 font-display text-6xl leading-[0.95]">{restaurant.name}</h2>
          <p className="mt-3 text-sm text-muted-foreground">{streetOf(restaurant.address)}</p>
        </div>
        {restaurant.score === null ? null : (
          <div className="text-right" style={{ "--score": restaurant.score }}>
            <div className="font-display text-[7.5rem] leading-[0.8] tabular heat-text">
              {formatScore(restaurant.score)}
            </div>
            <div className="mt-3 text-sm text-muted-foreground">{tierOf(restaurant.score)} · days 1–7</div>
          </div>
        )}
      </header>

      {standing === "ranked" ? (
        <div className="flex items-center gap-4 rounded-xl border bg-card px-5 py-4">
          <DoorOpen className="size-5 shrink-0 text-open-dot" />
          {next ? (
            <div className="text-sm">
              <div className="text-muted-foreground">Earliest way in</div>
              <div className="mt-0.5 font-medium tabular">
                {formatDay(next.diningDate)} · {formatTime(next.slot.time)} · {next.slot.type}
                {next.slot.price ? <span className="text-muted-foreground"> · {next.slot.price}</span> : null}
              </div>
            </div>
          ) : (
            <div className="text-sm">
              <div className="font-medium">No 6–9 PM table for two in the next 28 days</div>
              <div className="mt-0.5 text-muted-foreground">Every released dinner date was without an opening.</div>
            </div>
          )}
        </div>
      ) : null}

      <RestaurantDetail restaurant={restaurant} header={false} />
    </article>
  );
}

// PROTOTYPE — Layout C: restaurants × 28 dinner dates. Scarcity reads as a visible pattern.
import { Fragment } from "react";
import { cn } from "cn";

import { Sheet, SheetContent, SheetDescription, SheetTitle } from "#/components/ui/sheet";

import {
  competitionRanks,
  dayOfMonth,
  formatMonthDay,
  formatScore,
  groupByStanding,
  headline,
  isWeekend,
  standingOf,
  streetOf,
  weekdayLetter,
} from "./dashboard.ts";
import type { Band, Restaurant } from "./dashboard.ts";
import type { Dashboard } from "./dashboard.server.ts";
import { CollectionFacts, DayCell, Legend, MethodNotes, RestaurantDetail, bandGap } from "./parts.tsx";

const BAND_STARTS = [1, 8, 15, 22];

const DAY_COLUMNS = 28 + BAND_STARTS.length;

export function HeatmapLayout({
  dashboard,
  venue,
  onSelectVenue,
}: {
  dashboard: Dashboard;
  venue: string | undefined;
  onSelectVenue: (slug: string | undefined) => void;
}) {
  const groups = groupByStanding(dashboard.restaurants);
  const ranks = competitionRanks(groups[0].restaurants);
  const selected = dashboard.restaurants.find((restaurant) => restaurant.slug === venue);
  const calendar = dashboard.restaurants[0]?.days ?? [];

  return (
    <main className="mx-auto max-w-[1480px] px-6 pt-14 pb-36">
      <header className="flex flex-wrap items-end justify-between gap-x-10 gap-y-5">
        <div>
          <p className="text-xs font-medium text-muted-foreground">Resy · San Francisco · Party of 2 · 6–9 PM</p>
          <h1 className="mt-3 font-display text-5xl leading-none">Where the tables go</h1>
          <CollectionFacts className="mt-4" collections={dashboard.collections} total={dashboard.restaurants.length} />
        </div>
        <Legend />
      </header>

      <div className="mt-10 overflow-x-auto rounded-xl border bg-card">
        <table className="w-full min-w-[1180px] border-separate border-spacing-0 text-sm">
          <thead className="text-xs text-muted-foreground">
            <tr>
              <th rowSpan={2} className="sticky left-0 z-20 w-12 border-b bg-card pl-5 text-left font-medium">#</th>
              <th rowSpan={2} className="sticky left-12 z-20 w-56 border-b bg-card text-left font-medium">Restaurant</th>
              <th rowSpan={2} className="sticky left-68 z-20 w-16 border-r border-b bg-card pr-4 text-right font-medium">
                Score
              </th>
              {BAND_STARTS.map((start) => (
                <th
                  key={start}
                  colSpan={8}
                  className={cn("border-l px-2 pt-4 pb-1 text-left font-medium", start === 1 && "border-l-0 text-foreground")}
                >
                  {start === 1 ? "Headline week" : `Days ${start}–${start + 6}`}
                  {calendar[start - 1] ? (
                    <span className="ml-2 font-normal text-faint">
                      {formatMonthDay(calendar[start - 1].diningDate)}–{formatMonthDay(calendar[start + 5].diningDate)}
                    </span>
                  ) : null}
                </th>
              ))}
            </tr>
            <tr>
              {calendar.map((day) => (
                <Fragment key={day.diningDate}>
                  <th
                    className={cn(
                      "border-b px-0.5 pb-2 text-center font-normal",
                      day.offset % 7 === 1 && day.offset > 1 && "border-l",
                      isWeekend(day.diningDate) && "text-foreground",
                    )}
                  >
                    <div className="text-[10px]">{weekdayLetter(day.diningDate)}</div>
                    <div className="text-[10px] text-faint tabular">{dayOfMonth(day.diningDate)}</div>
                  </th>
                  {day.offset % 7 === 0 ? <th className="w-10 border-b pb-2 text-[10px] font-normal text-faint">Band</th> : null}
                </Fragment>
              ))}
            </tr>
          </thead>
          {groups.map((group) =>
            group.restaurants.length === 0 ? null : (
              <tbody key={group.standing}>
                {group.standing === "ranked" ? null : (
                  <tr>
                    <td colSpan={3} className="sticky left-0 z-10 border-r bg-muted px-5 pt-6 pb-2">
                      <span className="text-xs font-medium">{group.title}</span>
                      <span className="ml-2 text-xs text-muted-foreground tabular">{group.restaurants.length}</span>
                    </td>
                    <td colSpan={DAY_COLUMNS} className="bg-muted px-3 pt-6 pb-2 text-xs text-muted-foreground">
                      {group.note}
                    </td>
                  </tr>
                )}
                {group.restaurants.map((restaurant) => (
                  <MatrixRow
                    key={restaurant.slug}
                    restaurant={restaurant}
                    rank={ranks.get(restaurant.slug)}
                    selected={restaurant.slug === venue}
                    onSelect={() => onSelectVenue(restaurant.slug)}
                  />
                ))}
              </tbody>
            ),
          )}
        </table>
      </div>

      <section className="mt-16 border-t pt-10">
        <h2 className="mb-8 font-display text-2xl">How the score works</h2>
        <MethodNotes collections={dashboard.collections} />
      </section>

      <Sheet open={selected !== undefined} onOpenChange={(open) => (open ? null : onSelectVenue(undefined))}>
        <SheetContent className="w-full overflow-y-auto p-8 sm:max-w-2xl">
          <SheetTitle className="sr-only">{selected?.name}</SheetTitle>
          <SheetDescription className="sr-only">Scarcity evidence for {selected?.name}</SheetDescription>
          {selected ? <RestaurantDetail restaurant={selected} /> : null}
        </SheetContent>
      </Sheet>
    </main>
  );
}

function MatrixRow({
  restaurant,
  rank,
  selected,
  onSelect,
}: {
  restaurant: Restaurant;
  rank: { rank: number; tied: boolean } | undefined;
  selected: boolean;
  onSelect: () => void;
}) {
  const standing = standingOf(restaurant);
  const hasObservations = restaurant.days.some((day) => day.observation !== null);
  const band = headline(restaurant);
  const rowTone = standing === "ranked" ? "" : "text-muted-foreground";

  return (
    <tr
      onClick={onSelect}
      className={cn("group cursor-pointer", rowTone)}
      style={{ "--score": restaurant.score ?? 0 }}
    >
      <td className={cn("sticky left-0 z-10 border-b bg-card py-2 pl-5 font-mono text-xs text-faint tabular group-hover:bg-accent", selected && "bg-accent")}>
        {rank ? `${rank.tied ? "T" : ""}${rank.rank}` : "—"}
      </td>
      <td className={cn("sticky left-12 z-10 max-w-56 border-b bg-card py-2 pr-3 group-hover:bg-accent", selected && "bg-accent")}>
        <button type="button" className="block max-w-full truncate text-left font-medium text-foreground outline-none focus-visible:underline">
          {restaurant.name}
        </button>
        <div className="truncate text-[11px] text-muted-foreground">{streetOf(restaurant.address)}</div>
      </td>
      <td className={cn("sticky left-68 z-10 border-r border-b bg-card py-2 pr-4 text-right group-hover:bg-accent", selected && "bg-accent")}>
        {restaurant.score === null ? (
          <span className="text-faint">—</span>
        ) : (
          <span className="font-display text-xl leading-none tabular heat-text">{formatScore(restaurant.score)}</span>
        )}
      </td>
      {hasObservations ? (
        restaurant.days.map((day) => (
          <Fragment key={day.diningDate}>
            <td className={cn("border-b px-0.5 py-2 group-hover:bg-accent/50", day.offset % 7 === 1 && day.offset > 1 && "border-l", isWeekend(day.diningDate) && "bg-foreground/[0.025]")}>
              <DayCell day={day} className="mx-auto size-5" />
            </td>
            {day.offset % 7 === 0 ? (
              <BandCell band={restaurant.bands.find((item) => item.startDay === day.offset - 6)} />
            ) : null}
          </Fragment>
        ))
      ) : (
        <td colSpan={DAY_COLUMNS} className="border-b px-3 py-2 text-xs italic group-hover:bg-accent/50">
          {restaurant.eligibilityReason}
        </td>
      )}
      {standing === "incomplete" && band ? <td className="sr-only">{bandGap(band)}</td> : null}
    </tr>
  );
}

function BandCell({ band }: { band: Band | undefined }) {
  if (!band || band.score === null) {
    return (
      <td className="border-b px-1 text-center font-mono text-[11px] text-faint" title={band ? (bandGap(band) ?? undefined) : undefined}>
        —
      </td>
    );
  }

  return (
    <td className="border-b px-1 text-center font-mono text-[11px] tabular heat-text" style={{ "--score": band.score }}>
      {formatScore(band.score)}
    </td>
  );
}

