// PROTOTYPE — three layouts × three styles of the ranking, switchable via ?layout= and ?style=.
import { createFileRoute } from "@tanstack/react-router";
import { z } from "zod";

import { getDashboard } from "#/prototype/dashboard.functions.ts";
import { HeatmapLayout } from "#/prototype/layout-heatmap.tsx";
import { LeaderboardLayout } from "#/prototype/layout-leaderboard.tsx";
import { LedgerLayout } from "#/prototype/layout-ledger.tsx";
import { LAYOUT_KEYS, PrototypeSwitcher, STYLE_KEYS } from "#/prototype/switcher.tsx";

const searchSchema = z.object({
  layout: z.enum(LAYOUT_KEYS).default("table").catch("table"),
  style: z.enum(STYLE_KEYS).default("obsidian").catch("obsidian"),
  venue: z.string().optional().catch(undefined),
});

export const Route = createFileRoute("/")({
  validateSearch: searchSchema,
  loader: () => getDashboard(),
  component: Home,
});

function Home() {
  const dashboard = Route.useLoaderData();
  const { layout, style, venue } = Route.useSearch();
  const navigate = Route.useNavigate();

  function selectVenue(slug: string | undefined) {
    void navigate({ search: (previous) => ({ ...previous, venue: slug }), replace: true, resetScroll: false });
  }

  const layoutProps = { dashboard, venue, onSelectVenue: selectVenue };

  return (
    <div data-style={style} className="min-h-screen">
      {layout === "table" ? <LedgerLayout {...layoutProps} /> : null}
      {layout === "leaderboard" ? <LeaderboardLayout {...layoutProps} /> : null}
      {layout === "heatmap" ? <HeatmapLayout {...layoutProps} /> : null}
      <PrototypeSwitcher
        layout={layout}
        style={style}
        onLayout={(next) => void navigate({ search: (previous) => ({ ...previous, layout: next }), replace: true })}
        onStyle={(next) =>
          void navigate({ search: (previous) => ({ ...previous, style: next }), replace: true, resetScroll: false })
        }
      />
    </div>
  );
}

