@custom-variant dark (&:is(.dark *));

/*
 * Paper: ink on white. Text pairs meet WCAG AA on --card and --background.
 * Scarcity tokens: --heat-low/--heat-high form the fixed 0–100 score ramp;
 * --booked/--open/--closed/--pending/--warn encode dinner-date status.
 */
:root {
  color-scheme: light;

  --background: #fafafa;
  --foreground: #0a0a0a;
  --card: #ffffff;
  --card-foreground: #0a0a0a;
  --popover: #0a0a0a;
  --popover-foreground: #fafafa;
  --primary: #0a0a0a;
  --primary-foreground: #ffffff;
  --secondary: #f2f2f2;
  --secondary-foreground: #0a0a0a;
  --muted: #f4f4f4;
  --muted-foreground: #5f5f5f;
  --faint: #737373;
  --accent: #f2f2f2;
  --accent-foreground: #0a0a0a;
  --destructive: #d93036;
  --border: #e6e6e6;
  --input: #e6e6e6;
  --ring: #0070f3;
  --radius: 0.375rem;

  --heat-low: #737373;
  --heat-high: #0a0a0a;
  --booked: #0a0a0a;
  --open: #ffffff;
  --open-ring: #cfcfcf;
  --open-dot: #0070f3;
  --closed: #c4c4c4;
  --pending: #8f8f8f;
  --warn: #b45309;
}

@theme inline {
  --font-sans: "Geist Variable", ui-sans-serif, system-ui, sans-serif;
  --font-mono: "Geist Mono Variable", ui-monospace, monospace;
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-faint: var(--faint);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-warn: var(--warn);
  --color-open-dot: var(--open-dot);
  --radius-sm: calc(var(--radius) - 4px);
  --radius-md: calc(var(--radius) - 2px);
  --radius-lg: var(--radius);
  --radius-xl: calc(var(--radius) + 4px);
}

@layer base {
  * {
    @apply border-border outline-ring/60;
  }

  body {
    margin: 0;
    min-height: 100vh;
    background-color: var(--background);
    background-image: radial-gradient(circle at 1px 1px, rgb(0 0 0 / 0.07) 1px, transparent 0);
    background-size: 18px 18px;
    background-attachment: fixed;
    color: var(--foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
  }
}

@utility tabular {
  font-variant-numeric: tabular-nums;
}

/* Score colour on the fixed 0–100 ramp; set --score on the element or an ancestor. */
@utility heat-text {
  color: color-mix(in oklch, var(--heat-high) calc(var(--score) * 1%), var(--heat-low));
}

@utility heat-fill {
  background: color-mix(in oklch, var(--heat-high) calc(var(--score) * 1%), var(--heat-low));
}

/* Day cells encode status by fill and pattern as well as colour. */
.day-cell {
  position: relative;
  display: block;
  aspect-ratio: 1;
  border-radius: 3px;
}

.day-cell[data-status="unavailable"] {
  background: var(--booked);
}

.day-cell[data-status="available"] {
  background: var(--open);
  box-shadow: inset 0 0 0 1px var(--open-ring);
}

.day-cell[data-status="available"]::after {
  content: "";
  position: absolute;
  inset: 34%;
  border-radius: 999px;
  background: var(--open-dot);
}

.day-cell[data-status="non_service"] {
  background: repeating-linear-gradient(135deg, var(--closed) 0 1.5px, transparent 1.5px 4.5px);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--closed) 60%, transparent);
}

.day-cell[data-status="unreleased"] {
  outline: 1px dashed var(--pending);
  outline-offset: -1px;
}

.day-cell[data-status="unknown"],
.day-cell[data-status="collection_error"],
.day-cell[data-status="unchecked"] {
  background: color-mix(in oklch, var(--warn) 8%, white);
  box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--warn) 45%, transparent);
}

.day-cell[data-status="unknown"]::after,
.day-cell[data-status="collection_error"]::after,
.day-cell[data-status="unchecked"]::after {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
  color: var(--warn);
  font: 600 0.6em/1 var(--font-mono);
}

.day-cell[data-status="unknown"]::after {
  content: "?";
}

.day-cell[data-status="collection_error"]::after {
  content: "!";
}

.day-cell[data-status="unchecked"]::after {
  content: "–";
}

