function observationFor(
  code: string,
  diningDate: string,
  evidence: Evidence,
  slots: Slot[],
): Observation | null {
  const base = { diningDate, observedAt: evidence.observedAt, evidence: [evidence] };

  switch (code) {
    case "A": {
      // Vary the visible slots by date so openings do not all look identical.
      const count = 1 + (Number(diningDate.slice(-2)) % Math.max(slots.length, 1));

      return { ...base, status: "available", slots: slots.slice(0, count) };
    }
    case "U":
      return {
        ...base,
        status: "unavailable",
        releaseEvidence: { ...evidence, quote: "Calendar shows this date as released" },
        serviceEvidence: { ...evidence, quote: "Dinner service listed for this weekday" },
      };
    case "N":
      return { ...base, status: "non_service" };
    case "R":
      return { ...base, status: "unreleased" };
    case "?":
      return { ...base, status: "unknown" };
    case "E":
      return { ...base, status: "collection_error" };
    case "-":
      return null;
    default:
      throw new Error(`Unknown sample day code: ${code}`);
  }
}

function capture(venue: SampleVenue, index: number): RestaurantCapture {
  const resyUrl = `https://resy.com/cities/san-francisco-ca/venues/${venue.slug}`;
  const anchor = localDate(STARTED_AT);
  const eligibility = venue.eligibility ?? "eligible";
  const reason = venue.reason ?? "Regular public dinner reservations for two on Resy";
  // Spread venues across the collection interval, one minute apart.
  const observedAt = new Date(Date.parse(STARTED_AT) + index * 60_000).toISOString();
  const evidence = { url: resyUrl, observedAt, quote: reason };
  const observations: Observation[] = [];

  for (const [offset, code] of (venue.days ?? "").replaceAll(" ", "").split("").entries()) {
    const observation = observationFor(
      code,
      addDays(anchor, offset + 1),
      evidence,
      venue.slots ?? [],
    );

    if (observation) {
      observations.push(observation);
    }
  }

  return {
    name: venue.name,
    resyUrl,
    address: venue.address,
    geography: venue.geography ?? "san_francisco",
    eligibility,
    reason,
    bookingPolicy: venue.bookingPolicy ?? null,
    evidence: [evidence],
    observations,
  };
}

/** Derives the stored record the way import and the `restaurant_ranking` view do. */
function record(restaurant: RestaurantCapture, anchorDate: string): RestaurantRecord {
  const bands = scoreRestaurant(restaurant, anchorDate).map((band) => ({
    collectionId: COLLECTION_ID,
    resyUrl: restaurant.resyUrl,
    startDay: band.startDay,
    endDay: band.endDay,
    available: band.counts.available,
    unavailable: band.counts.unavailable,
    nonService: band.counts.non_service,
    unreleased: band.counts.unreleased,
    unknown: band.counts.unknown,
    collectionError: band.counts.collection_error,
    missing: band.counts.missing,
    assessed: band.assessed,
    score: band.score,
    reason: band.reason,
  }));

  const [headline] = bands;
  const openDates = restaurant.observations
    .filter((observation) => observation.status === "available")
    .map((observation) => observation.diningDate)
    .toSorted();

  const weekendOpenDates = openDates.filter((date) => {
    const weekday = new Date(`${date}T12:00:00Z`).getUTCDay();

    return weekday === 5 || weekday === 6;
  });

  return {
    resyUrl: restaurant.resyUrl,
    name: restaurant.name,
    address: restaurant.address,
    collectionId: COLLECTION_ID,
    observedFrom: STARTED_AT,
    observedThrough: FINISHED_AT,
    anchorDate,
    geography: restaurant.geography,
    eligibility: restaurant.eligibility,
    eligibilityReason: restaurant.reason,
    bookingPolicy: restaurant.bookingPolicy,
    score: headline.score,
    scoreReason: headline.reason,
    assessed: headline.assessed,
    available: headline.available,
    unavailable: headline.unavailable,
    nonService: headline.nonService,
    unreleased: headline.unreleased,
    unknown: headline.unknown,
    collectionError: headline.collectionError,
    missing: headline.missing,
    earliestAvailableDate: openDates[0] ?? null,
    weekendAvailableDates: weekendOpenDates.length,
    evidence: restaurant.evidence,
    bands,
    observations: restaurant.observations,
  };
}

export function sampleRankingData(venues: SampleVenue[] = SAMPLE_VENUES): RankingData {
  const collection = collectionSchema.parse({
    schemaVersion: 1,
    id: COLLECTION_ID,
    startedAt: STARTED_AT,
    finishedAt: FINISHED_AT,
    discoveryUrl: "https://resy.com/cities/san-francisco-ca",
    discoveryComplete: false,
    selection: "Sample data: fictional venues covering every eligibility and dinner-date state",
    collector: "src/ranking/sample-data.ts",
    procedure: ["Generate fictional venues from explicit 28-day status patterns"],
    limitations: [
      "Fictional venues; not a Resy observation",
      "Partial listing; not a citywide census",
    ],
    restaurants: venues.map(capture),
  });
  const anchorDate = localDate(collection.startedAt);

  return {
    collections: [
      {
        id: collection.id,
        startedAt: collection.startedAt,
        finishedAt: collection.finishedAt,
        anchorDate,
        discoveryComplete: collection.discoveryComplete,
        selection: collection.selection,
        limitations: collection.limitations,
      },
    ],
    restaurants: collection.restaurants.map((restaurant) => record(restaurant, anchorDate)),
  };
}

