import { describe, expect, it } from "vite-plus/test";

import { sampleRankingData } from "./sample-data.ts";
import type { SampleVenue } from "./sample-data.ts";
import { buildRanking, initialSort, sortRanked } from "./view-model.ts";

function venue(name: string, days: string, overrides: Partial<SampleVenue> = {}): SampleVenue {
  const slug = name.toLowerCase().replaceAll(" ", "-");

  return {
    slug,
    name,
    address: `1 ${name} St, San Francisco, CA 94110`,
    days,
    slots: [{ time: "19:00", type: "Dining room", price: null }],
    ...overrides,
  };
}

function rankingOf(...venues: SampleVenue[]) {
  return buildRanking(sampleRankingData(venues));
}

describe("buildRanking", () => {
  it("ranks only eligible venues with a complete headline week", () => {
    const ranking = rankingOf(
      venue("Booked", "UUUUUUU"),
      venue("Closed", "UUUUUUU", { eligibility: "excluded", reason: "Permanently closed" }),
      venue("Notify Only", "???????", { eligibility: "unresolved", reason: "Only “Notify”" }),
      venue("Short Window", "UUUUUUR"),
    );

    expect(ranking.ranked.map((entry) => [entry.restaurant.name, entry.score])).toEqual([
      ["Booked", 100],
    ]);
    expect(
      ranking.unranked.map((group) => [
        group.standing,
        group.entries.map((entry) => [entry.restaurant.name, entry.reason]),
      ]),
    ).toEqual([
      ["unscored", [["Short Window", "1 not released"]]],
      ["unresolved", [["Notify Only", "Only “Notify”"]]],
      ["excluded", [["Closed", "Permanently closed"]]],
    ]);
  });

  it("gives tied scores one shared position and skips the next", () => {
    const ranking = rankingOf(
      venue("Open", "UAAAAAA"),
      venue("Zinc", "UUUUUUU"),
      venue("Alder", "UUUUUUU"),
    );

    expect(
      ranking.ranked.map(({ restaurant, rank }) => [restaurant.name, rank.position, rank.tied]),
    ).toEqual([
      ["Alder", 1, true],
      ["Zinc", 1, true],
      ["Open", 3, false],
    ]);
  });

  it("marks unobserved dates as not checked and finds the earliest opening", () => {
    const ranking = rankingOf(
      venue("Early", "NA", {
        slots: [
          { time: "21:00", type: "Bar", price: null },
          { time: "18:30", type: "Dining room", price: null },
        ],
      }),
    );
    const [entry] = ranking.unranked[0].entries;

    expect(entry.days).toHaveLength(28);
    expect(entry.days.slice(0, 3).map((day) => [day.diningDate, day.status])).toEqual([
      ["2026-10-01", "non_service"],
      ["2026-10-02", "available"],
      ["2026-10-03", "missing"],
    ]);
    expect(entry.nextOpening).toEqual({
      diningDate: "2026-10-02",
      slot: { time: "18:30", type: "Dining room", price: null },
    });
  });
});

describe("sortRanked", () => {
  it("first sorts by next opening with the hardest tables on top", () => {
    const { ranked } = rankingOf(
      venue("Soon", "AUUUUUU"),
      venue("Never", "UUUUUUU"),
      venue("Later", "UUUUUUU A"),
    );

    const names = sortRanked(ranked, initialSort("opening")).map((entry) => entry.restaurant.name);

    expect(names).toEqual(["Never", "Later", "Soon"]);
  });
});

